package com.eu.habbo.networking.gameserver.auth;
import io.netty.channel.*;import io.netty.channel.embedded.EmbeddedChannel;import io.netty.handler.codec.http.*;import org.junit.jupiter.api.Test;import static org.junit.jupiter.api.Assertions.*;
class WebsiteAccountEndpointsTest {
 private FullHttpResponse request(HttpMethod method,String path,String token){EmbeddedChannel channel=new EmbeddedChannel(new ChannelInboundHandlerAdapter(){@Override public void channelRead(ChannelHandlerContext ctx,Object msg){FullHttpRequest req=(FullHttpRequest)msg;try{WebsiteAccountEndpoints.handle(ctx,req,path.split("\\?")[0]);}finally{req.release();}}});FullHttpRequest req=new DefaultFullHttpRequest(HttpVersion.HTTP_1_1,method,path);req.headers().set(HttpHeaderNames.HOST,"hotel.example");if(token!=null)req.headers().set(HttpHeaderNames.AUTHORIZATION,"Bearer "+token);channel.writeInbound(req);FullHttpResponse result=channel.readOutbound();channel.finishAndReleaseAll();return result;}
 @Test void anonymousAndForgedSessionsCannotReadAnyAccount(){for(String token:new String[]{null,"bad","hws_bad"}){FullHttpResponse r=request(HttpMethod.GET,"/api/community/account?userId=1",token);try{assertEquals(401,r.status().code());assertEquals("no-store",r.headers().get("Cache-Control"));assertFalse(r.content().toString(java.nio.charset.StandardCharsets.UTF_8).contains("email"));}finally{r.release();}}}
 @Test void profileDoesNotAcceptWriteMethods(){FullHttpResponse r=request(HttpMethod.POST,"/api/community/account",null);try{assertEquals(405,r.status().code());}finally{r.release();}}
 @Test void accountActionsRejectRequestsWithoutSameOrigin(){FullHttpResponse r=request(HttpMethod.POST,"/api/community/account/logout",null);try{assertEquals(403,r.status().code());}finally{r.release();}}
}
